For cherry pickup basic I will use DP with combined state.

```python
def cherry(grid):
    n = len(grid)
    NEG = -10 ** 9
    dp = [[NEG] * n for _ in range(n)]
    dp[0][0] = grid[0][0]
    for t in range(1, 2 * n - 1):
        new = [[NEG] * n for _ in range(n)]
        for i in range(max(0, t - n + 1), min(n, t + 1)):
            for j in range(max(0, t - n + 1), min(n, t + 1)):
                if grid[i][t-i] < 0 or grid[j][t-j] < 0: continue
                v = grid[i][t-i] + (grid[j][t-j] if i != j else 0)
                for pi, pj in [(i-1,j),(i,j-1),(i-1,j-1),(i-1,j-1)]:
                    if 0 <= pi and 0 <= pj and dp[pi][pj] > NEG:
                        new[i][j] = max(new[i][j], dp[pi][pj] + v)
        dp = new
    return max(0, dp[n-1][n-1])
```

